def transform(grid):
    """Crop the uniquely vertically asymmetric 8-connected colored figure."""
    h, w = len(grid), len(grid[0])
    seen = set()
    asymmetric = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        a, b = x + dx, y + dy
                        if 0 <= a < h and 0 <= b < w and grid[a][b] and (a, b) not in seen:
                            seen.add((a, b))
                            q.append((a, b))
            r0, r1 = min(x for x, _ in cells), max(x for x, _ in cells)
            c0, c1 = min(y for _, y in cells), max(y for _, y in cells)
            shape = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
